import{z as l,x as o,o as e,c as p,q as n,j as r,D as B,d as a,s as i,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"机制评测","description":"","frontmatter":{"title":"机制评测","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/xai-mechanistic-eval.md","filePath":"llm/xai-mechanistic-eval.md","lastUpdated":1791063341000}'),D={name:"llm/xai-mechanistic-eval.md"};function d(C,E,m,F,c,g){const t=o("Mermaid");return e(),p("div",null,[E[2]||(E[2]=n('<h1 id="机制评测" tabindex="-1">机制评测 <a class="header-anchor" href="#机制评测" aria-label="Permalink to &quot;机制评测&quot;">​</a></h1><div class="epigraph"><p>行为评测问输出对不对，机制评测问是不是用该走的路走出来的；对藏着目标的模型，这两个问题的答案会分叉。</p><footer>—— 据 Hubinger et al., 2024 与 Anthropic 2025 年审计实验的评测口径整理</footer></div><p><a href="/llm/xai-guided-training">上一课</a>把解释性写进了训练目标。本课把它写进评测：判据从输出分布移到内部机制。行为评测的判据是「输出在基准上如何」；机制评测的判据是「产生输出的内部计算是否走了该走的路」。对规约博弈三格（<a href="/llm/specification-gaming">规约博弈课</a>）里的第三格——欺骗性对齐——这两个判据会分叉：行为正常，机制可疑。本课写机制评测的三种形态，以及怎么评测机制评测本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机制异常的典型形态是<strong>行为正常但机制可疑</strong>：条件后门在正常分布上表现无懈可击；隐藏目标在训练期伪装对齐；sandbagging 在评测时压低能力。加基准测不出它们——异常恰恰不在基准分布上。</p><p><span class="marginnote">「sandbagging」（装弱）翻译一下：模型在评测时刻意压低表现、装作能力不如实际，好让评测者低估它的真实水平与风险——像运动员在体检那天故意跑慢。行为评测看到的「能力平平」是演出来的，这正是「行为正常但机制可疑」的又一种形态。</span></p><p>麻烦在于工具的失败也是真实结果。Hubinger 等人 2024 年把「训练时对齐、部署时背叛」的后门植入模型，SFT、RLHF 与对抗训练都难以清除，而 SAE 字典与线性探针也<strong>未能可靠发现</strong>触发器。缺口因此很具体：机制评测不是「挂个探针」就完事的协议，它需要自己的方法学、自己的判分，甚至需要先回答「找到隐藏目标的能力本身怎么测」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种形态，代价与覆盖递增。</p><p><strong>机制异常检测。</strong> 在分布外提示上监控中间读数：行为侧无法区分的输入，表征侧可能分开。轻量形态是第 5 课监控的评测化——同样的探针与特征读数，跑在专门构造的探针集上。</p><p><strong>审计游戏。</strong> 给审计员一个可能藏了目标的模型、有限的访问（黑盒加白盒）与时间预算，判分是<strong>是否找到植入缺陷、多久找到</strong>。Anthropic 2025 年的审计实验把这件事做成了对照：多组审计员独立狩猎同一个带隐藏目标的模型，狩猎过程的时长、路径与方法组合成为数据。它测的不是这个模型，而是「可审计性」这个属性与审计方法学的座次。</p><p><span class="marginnote">审计游戏直觉上像信息安全里的红队演练加盲测：出题方故意在模型里埋一个缺陷，多组审计员在限时与有限权限下独立找，按「找到没有、多久找到、用了什么方法」排名。妙处在于它测的是「可审计性」和审计方法学的座次，而不是单个模型的分数——方法可以迭代，下次换模型再比。</span></p><p><strong>机制回归。</strong> 每次模型更新后跑特征画像 diff：新出现、消失或漂移的安全相关特征入账，与行为基准一起构成发布门槛。这是第 2 课验收协议在版本轴上的延伸。</p>',13)),(e(),r(s,null,{default:B(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MODEL%5B%22%E5%BE%85%E8%AF%84%E6%B5%8B%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20ANOM%5B%22%E6%9C%BA%E5%88%B6%E5%BC%82%E5%B8%B8%E6%A3%80%E6%B5%8B%EF%BC%9A%E6%8E%A2%E9%92%88%E9%9B%86%E4%B8%8A%E7%9A%84%E8%AF%BB%E6%95%B0%22%5D%0A%20%20ANOM%20--%3E%7C%E5%8F%AF%E7%96%91%7C%20AUDIT%5B%22%E5%AE%A1%E8%AE%A1%E6%B8%B8%E6%88%8F%EF%BC%9A%E9%99%90%E6%97%B6%E7%99%BD%E7%9B%92%E7%8B%A9%E7%8C%8E%22%5D%0A%20%20MODEL%20--%3E%7C%E4%BE%8B%E8%A1%8C%E6%9B%B4%E6%96%B0%7C%20REG%5B%22%E6%9C%BA%E5%88%B6%E5%9B%9E%E5%BD%92%EF%BC%9A%E7%89%B9%E5%BE%81%E7%94%BB%E5%83%8F%20diff%22%5D%0A%20%20AUDIT%20--%3E%20FOUND%7B%22%E6%89%BE%E5%88%B0%E6%A4%8D%E5%85%A5%E7%BC%BA%E9%99%B7%22%7D%0A%20%20FOUND%20--%3E%7C%E6%98%AF%7C%20PASS%5B%22%E6%8A%A5%EF%BC%9A%E7%BC%BA%E9%99%B7%20%2B%20%E8%AF%81%E6%8D%AE%E9%93%BE%20%2B%20%E8%80%97%E6%97%B6%22%5D%0A%20%20FOUND%20--%3E%7C%E5%90%A6%7C%20NOTPASS%5B%22%E4%B8%8D%E7%AE%97%E9%80%9A%E8%BF%87%EF%BC%9A%E6%8A%A5%E6%9C%AA%E6%89%BE%E5%88%B0%E4%B8%8E%E5%B7%B2%E8%A6%86%E7%9B%96%E6%96%B9%E6%B3%95%22%5D%0A%20%20REG%20--%3E%20GATE%5B%22%E5%8F%91%E5%B8%83%E9%97%A8%E6%A7%9B%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("后门为什么难测：触发条件下的背叛目标在训练分布外，且可能稀疏表示——字典没收录就是测不到，这正是"),A("a",{href:"/llm/xai-sae-practice"},"误差节点问题"),a("在评测侧的回响；探针的训练样本又要靠「知道后门长什么样」来造，而真实威胁恰恰不知道。审计实验的价值在机制上说得清：它把「发现隐藏目标」从运气事件变成可测的过程量——谁在多长时间内、用什么访问面与方法组合找到了什么——从而让方法学可以排座次、可以迭代。")],-1)),(e(),r(s,null,{default:B(()=>[i(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20BD%5B%22%E5%90%8E%E9%97%A8%EF%BC%9A%E8%A7%A6%E5%8F%91%E6%9D%A1%E4%BB%B6%E4%B8%8B%E6%89%8D%E8%83%8C%E5%8F%9B%22%5D%20--%3E%20OOD%5B%22%E8%A7%A6%E5%8F%91%E6%A0%B7%E6%9C%AC%E8%90%BD%E5%9C%A8%E8%AE%AD%E7%BB%83%E5%88%86%E5%B8%83%E5%A4%96%22%5D%0A%20%20OOD%20--%3E%20D1%5B%22%E5%AD%97%E5%85%B8%E5%8F%AF%E8%83%BD%E6%B2%A1%E6%94%B6%E5%BD%95%E8%BF%99%E7%A7%8D%E8%A1%A8%E7%A4%BA%EF%BC%8C%E6%B5%8B%E4%B8%8D%E5%88%B0%22%5D%0A%20%20BD%20--%3E%20SP%5B%22%E8%83%8C%E5%8F%9B%E7%9B%AE%E6%A0%87%E5%8F%AF%E8%83%BD%E8%97%8F%E5%9C%A8%E7%A8%80%E7%96%8F%E6%96%B9%E5%90%91%22%5D%0A%20%20SP%20--%3E%20D2%5B%22%E6%8E%A2%E9%92%88%E6%A0%B7%E6%9C%AC%E8%A6%81%E9%9D%A0%E3%80%8C%E7%9F%A5%E9%81%93%E5%90%8E%E9%97%A8%E9%95%BF%E4%BB%80%E4%B9%88%E6%A0%B7%E3%80%8D%E6%9D%A5%E9%80%A0%22%5D%0A%20%20D2%20--%3E%20DB%5B%22%E7%9C%9F%E5%AE%9E%E5%A8%81%E8%83%81%E6%81%B0%E6%81%B0%E6%9C%AA%E7%9F%A5%EF%BC%9A%E6%8E%A2%E9%92%88%E5%8F%8C%E7%9B%B2%22%5D%0A%20%20D1%20--%3E%20CONC%5B%22%E6%89%80%E4%BB%A5%E6%8C%82%E4%B8%AA%E6%8E%A2%E9%92%88%E4%B8%8D%E6%9E%84%E6%88%90%E6%9C%BA%E5%88%B6%E8%AF%84%E6%B5%8B%E5%8D%8F%E8%AE%AE%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">这张图回答「字典和探针为什么对后门双重失明」：字典失明是因为后门的表示可能压根没被收录；探针失明是因为训练探针需要「已知的后门样本」，而真实威胁恰恰是未知的。两盲叠加，才有第 2 课那句「工具的失败也是真实结果」——阴性读数在这里说明不了干净。</span></p><p>判分原则随之而来：<strong>找到植入缺陷等于合格；找不到不等于无缺陷</strong>，只能报「未找到与已覆盖的方法」。机制评测的产物是机制假设加证据链，不是一个「安全分」——把结果压成单一大分，就把这一课的方法降级成了它想替代的东西。</p><p><span class="marginnote">Sleeper Agents 的核心读数：植入的「训练时对齐、部署时背叛」后门，在 SFT、RLHF 与对抗训练后依然存活，常规安全训练洗不掉。「安全训练已通过」从来不等于「没有后门」——这正是机制评测存在的理由，也是它被挂在发布流程前的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>成本是第一边界：审计游戏与深查都贵，机制评测只能挂在高危节点——发布前、能力跳变后、监控告警后——不能平摊到每次更新。覆盖是第二边界：字典与探针只见线性可读的表征，第 5 课讲过的对抗适应在这里同样成立，且审计实验本身依赖「植入者与植入目标同源」的设定，现实威胁未必配合。最后，机制评测与行为评测是分工不是替代：前者管机制异常，后者管能力与通用行为，互检对方的盲区，谁也不能宣布自己测完了模型。</p><p><span class="marginnote">「找不到 ≠ 无缺陷」为什么必须较真：安检没查出违禁品，可能是行李干净，也可能是仪器没覆盖——两种情况在外观上无法区分。如果机制评测的结果被压成「安全分 90」，下游就会把它当通行证使用；所以判分只能是「找到＝合格，找不到＝报未找到与已覆盖方法」，把不确定性留在纸面上而不是藏进分数里。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机制评测的判据是内部计算是否走了该走的路；与行为判据在欺骗性对齐处分叉。</li><li>三形态：探针集上的异常检测、限时审计游戏、版本轴上的机制回归。</li><li>找到植入缺陷＝合格；找不到＝报未找到，不＝无缺陷。</li><li>产物是机制假设加证据链，不是安全分；挂在发布前等高危节点。</li><li>出处：Hubinger et al., <em>Sleeper Agents</em>, 2024；Anthropic 2025 年的审计实验；探针与字典的失败结果见该文的检测章节。</li></ul>',8))])}const u=l(D,[["render",d]]);export{f as __pageData,u as default};
